import type { StudyLesson } from "./study-content";

const cp = { label: "Código Penal — Decreto-Lei nº 2.848/1940 (texto compilado)", url: "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm" };
const cf = { label: "Constituição Federal de 1988 (texto compilado)", url: "https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm" };
const drogas = { label: "Lei de Drogas — Lei nº 11.343/2006 (texto compilado)", url: "https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11343.htm" };
const mariaPenha = { label: "Lei Maria da Penha — Lei nº 11.340/2006 (texto compilado)", url: "https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11340.htm" };
type ComparisonTable = { headers: string[]; rows: string[][] };
const section = (id: string, title: string, paragraphs: string[], points: string[], facts?: string, analysis?: string | ComparisonTable, table?: ComparisonTable) => {
  const comparison = typeof analysis === "object" ? analysis : table;
  const example = facts && typeof analysis === "string" ? { title: "Exemplo autoral", facts, analysis } : undefined;
  return { id, title, paragraphs, points, ...(example ? { example } : {}), ...(comparison ? { table: comparison } : {}) };
};
const review = (question: string, answer: string, explanation: string, basis: string) => ({ question, answer, explanation, basis });
type Option = { text: string; why: string };
const exercise = (id: string, prompt: string, correct: string, basis: string, options: [Option, Option, Option, Option]) => ({
  id, prompt, correctLabel: correct, basis,
  options: options.map((option, index) => ({ label: ["A", "B", "C", "D"][index], text: option.text, explanation: option.why })),
});

export const penalLessons: Record<string, StudyLesson> = {
  "penal-teoria-crime": {
    summary: ["Tipicidade, ilicitude e culpabilidade são planos sucessivos e distintos.", "A tipicidade exige correspondência legal e análise de conduta, resultado e nexo quando o tipo exigir.", "Dolo e culpa seguem as definições do art. 18; culpa só é punível quando prevista.", "Consumação e tentativa dependem da execução iniciada e da não consumação por circunstâncias alheias à vontade.", "Causas de exclusão devem ser ligadas ao elemento jurídico que afetam."],
    sections: [
      section("penal-teoria-crime-topico-1", "1. Legalidade penal e leitura do tipo", ["A Constituição protege a legalidade penal: não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal (CF, art. 5º, XXXIX; CP, art. 1º). A lei penal deve ser escrita, anterior, certa e estrita. A analogia não pode criar crime ou agravar pena contra o acusado.", "O tipo penal descreve uma conduta proibida ou ordenada e delimita a incidência da sanção. Ao ler a hipótese, identifique verbo, sujeito, objeto, circunstâncias, resultado e elemento subjetivo. Não acrescente fatos que o enunciado não informou.", "A legalidade também orienta a interpretação: termos do tipo devem ser compreendidos no sistema, sem estender a punição para além do texto possível. A lei posterior mais gravosa não retroage; a mais benéfica pode retroagir (CF, art. 5º, XL; CP, art. 2º)."], ["Lei anterior e determinada; proibição de analogia prejudicial.", "Interprete cada elemento do tipo e não complete lacunas fáticas.", "Confira a lei vigente ao tempo do fato e eventual lei posterior benéfica."], "Um regulamento administrativo descreve uma conduta reprovável, mas não há lei penal que a defina.", "A reprovação administrativa não basta para criar crime: a tipificação e a pena dependem de lei anterior, conforme CF, art. 5º, XXXIX e CP, art. 1º.", { headers: ["Garantia", "Consequência", "Base"], rows: [["Anterioridade", "A lei incriminadora deve preceder o fato.", "CP, arts. 1º e 2º."], ["Taxatividade", "A definição deve permitir conhecer a conduta proibida.", "CF, art. 5º, XXXIX."], ["Retroatividade benéfica", "Lei posterior favorável alcança fatos anteriores.", "CF, art. 5º, XL; CP, art. 2º, parágrafo único."]] }),
      section("penal-teoria-crime-topico-2", "2. Conduta, resultado e nexo causal", ["O fato típico começa pela conduta humana, ação ou omissão. Nos crimes materiais, o resultado naturalístico integra a consumação; nos formais e de mera conduta, a consumação segue a descrição legal, não dependendo necessariamente de resultado separado.", "Pelo art. 13 do CP, o resultado de que depende a existência do crime só é imputável a quem lhe deu causa; considera-se causa a ação ou omissão sem a qual o resultado não teria ocorrido. A teoria da equivalência dos antecedentes é ponto de partida legal, mas a imputação deve ser lida em conjunto com dolo/culpa e limites do tipo.", "A omissão pode ser penalmente relevante quando o omitente devia e podia agir para evitar o resultado (art. 13, § 2º). O dever de agir incumbe a quem tenha obrigação legal de cuidado, proteção ou vigilância; a quem assumiu responsabilidade de impedir o resultado; ou a quem criou o risco anterior. Não basta estar presente ou ser moralmente reprovável."], ["Crime material: resultado naturalístico exigido.", "Omissão imprópria: posição de garantidor + possibilidade concreta de agir + demais elementos.", "Nexo causal não substitui dolo ou culpa."], "Uma pessoa presencia acidente, mas não tinha dever jurídico especial, não criou o risco e não podia intervir com segurança.", "A omissão só é penalmente relevante nos termos do art. 13, § 2º; verificar possibilidade e posição de garantidor evita converter dever moral em responsabilidade penal automática."),
      section("penal-teoria-crime-topico-3", "3. Dolo, culpa e preterdolo", ["O art. 18, I, define dolo quando o agente quis o resultado ou assumiu o risco de produzi-lo. Dolo direto e eventual são formas estudadas a partir dessa definição, mas a conclusão depende dos fatos que revelem vontade ou aceitação do risco; gravidade do resultado, isoladamente, não prova dolo.", "O crime é culposo quando o agente dá causa ao resultado por imprudência, negligência ou imperícia (art. 18, II). A culpa exige violação do cuidado devido, previsibilidade objetiva e nexo, conforme o tipo. A modalidade culposa só é punível quando a lei prevê expressamente (art. 18, parágrafo único).", "No resultado agravador pelo qual o agente não quis nem assumiu o risco, o art. 19 exige que ao menos tenha agido culposamente para que responda pelo resultado que agrava especialmente a pena. O preterdolo combina dolo no antecedente e culpa no resultado agravador; não é responsabilidade penal objetiva."], ["Dolo: vontade ou assunção do risco (art. 18, I).", "Culpa: imprudência, negligência ou imperícia (art. 18, II).", "Crime culposo exige previsão legal; resultado agravador exige culpa (arts. 18, parágrafo único, e 19)."], "Durante manobra imprudente, motorista provoca lesão que não desejava.", "A análise deve verificar violação do dever de cuidado, previsibilidade e nexo para modalidade culposa; não se conclui por dolo apenas porque houve lesão."),
      section("penal-teoria-crime-topico-4", "4. Consumação, tentativa e desistência", ["O crime é consumado quando reúne todos os elementos da definição legal (CP, art. 14, I). A consumação depende do tipo: no crime material, do resultado; em outros, pode coincidir com a prática da conduta descrita.", "A tentativa ocorre quando, iniciada a execução, o crime não se consuma por circunstâncias alheias à vontade do agente (art. 14, II). A pena do crime consumado é reduzida de um a dois terços, salvo disposição em contrário (parágrafo único); a fração se relaciona ao iter criminis, conforme avaliação fundamentada.", "Na desistência voluntária e no arrependimento eficaz, o agente responde pelos atos já praticados, e não pelo resultado que evitou (art. 15). O arrependimento posterior do art. 16 tem requisitos próprios: crime sem violência ou grave ameaça à pessoa, reparação do dano ou restituição da coisa até o recebimento da denúncia ou queixa e ato voluntário do agente."], ["Tentativa: execução iniciada + não consumação por circunstância externa.", "Desistência voluntária: agente interrompe a execução; arrependimento eficaz: impede o resultado.", "Arrependimento posterior é causa de redução, não exclui crime (art. 16)."], "A pessoa inicia subtração e, podendo continuar, decide espontaneamente parar antes de qualquer circunstância externa impedir o resultado.", "Se houve desistência voluntária, aplica-se o art. 15: responde pelos atos já praticados, sem imputação automática da tentativa do crime inicialmente pretendido."),
      section("penal-teoria-crime-topico-5", "5. Erro de tipo e erro de proibição", ["Erro sobre elemento constitutivo do tipo exclui o dolo, mas permite punição culposa se prevista em lei (CP, art. 20). O erro deve recair sobre fato que compõe a descrição típica; desconhecimento da lei não é a mesma coisa.", "O erro sobre a ilicitude do fato, se inevitável, isenta de pena; se evitável, pode diminuí-la de um sexto a um terço (art. 21). Evitabilidade é avaliada pelas circunstâncias e pela possibilidade de alcançar consciência da ilicitude, não pelo simples argumento de que o agente não conhecia o artigo.", "Erro quanto à pessoa (art. 20, § 3º) não isenta de pena: consideram-se as condições ou qualidades da pessoa contra quem o agente queria praticar o crime. Erro sobre a existência ou limites de justificante putativa tem disciplina no art. 20, § 1º. Classifique primeiro o objeto do erro."], ["Erro de tipo: fato/elemento típico; afeta dolo.", "Erro de proibição: consciência potencial da ilicitude; pode isentar ou reduzir.", "Erro sobre pessoa não muda a consideração das qualidades da vítima pretendida."], "Uma pessoa leva guarda-chuva alheio acreditando, por circunstâncias justificáveis, que é o seu.", "O erro recai sobre elemento fático relativo à coisa alheia e pode afastar o dolo, nos termos do art. 20; eventual culpa só importa se houver previsão legal."),
      section("penal-teoria-crime-topico-6", "6. Concurso aparente de normas e especialidade", ["Um mesmo fato pode parecer caber em mais de um tipo. Antes de somar crimes, examine se há concurso aparente de normas: especialidade, subsidiariedade, consunção ou alternatividade são critérios de solução construídos a partir da estrutura normativa e do caso.", "Na especialidade, a norma especial contém elementos da geral e acrescenta característica específica. Na subsidiariedade, uma norma cede diante de delito mais grave que absorve a situação; a subsidiariedade pode ser expressa ou tácita. Na consunção, o crime-meio ou etapa normal pode ser absorvido pelo crime-fim, desde que haja relação concreta e não autonomia de desígnios/fatos puníveis.", "Esses critérios não autorizam apagar crimes autônomos. Compare bens jurídicos, condutas, momentos e desígnios; indique por que um tipo prevalece. O CP também prevê concurso material, formal e crime continuado nos arts. 69 a 71, que pressupõem pluralidade juridicamente relevante e não se confundem com conflito aparente."], ["Especialidade: tipo especial prevalece sobre geral.", "Consunção: absorção exige relação de meio/etapa normal e unidade contextual.", "Concurso real de crimes só após afastar absorção e conflito aparente."], "Uma conduta inicial é etapa normal e sem autonomia de um delito mais amplo, mas o enunciado informa também uma ação independente posterior.", "Não se deve aplicar consunção automaticamente. Verifique autonomia de condutas, bens jurídicos e desígnios; crime independente pode permanecer sujeito a concurso."),
      section("penal-teoria-crime-topico-7", "7. Roteiro de prova: do fato à consequência", ["Aplique uma ordem: lei penal no tempo e legalidade; conduta e resultado; tipicidade objetiva e subjetiva; nexo quando exigido; ilicitude e justificantes; culpabilidade; consumação/tentativa; concurso e consequência. Essa sequência evita saltar do resultado para a pena.", "A teoria analítica do crime é ferramenta de estudo: fato típico, ilicitude e culpabilidade são categorias distintas. As classificações podem variar em doutrina, por isso, em resposta objetiva, fundamente-se na lei e na distinção efetivamente cobrada.", "Os casos e exercícios desta aula são autorais, não são questões oficiais da OAB. O conteúdo é introdutório, não esgota a parte geral, e permanece pendente de revisão jurídica e pedagógica."], ["Localize em qual categoria está o problema.", "Não confunda ausência de tipicidade, justificante e exclusão de culpabilidade.", "Responda com artigo e requisito aplicados aos fatos."], "A alternativa afirma que houve crime apenas porque ocorreu um resultado grave.", "A gravidade não substitui tipicidade, nexo, dolo/culpa, ilicitude e culpabilidade; é preciso percorrer cada requisito."),
    ],
    reviewQuestions: [
      review("1. Qual é o núcleo da garantia de legalidade penal?", "Não há crime sem lei anterior que o defina nem pena sem prévia cominação legal.", "A garantia exige lei anterior e determinada e impede analogia prejudicial para criar incriminação.", "CF, art. 5º, XXXIX; CP, art. 1º."),
      review("2. Quando a omissão pode ser penalmente relevante para um resultado?", "Quando o omitente devia e podia agir para evitá-lo, nas hipóteses de posição de garantidor do art. 13, § 2º.", "A lei prevê fontes específicas do dever de agir; presença ou censura moral não bastam.", "CP, art. 13, § 2º."),
      review("3. Como o CP distingue dolo e culpa?", "Dolo envolve vontade ou assunção do risco; culpa decorre de imprudência, negligência ou imperícia.", "A culpa só é punível quando prevista expressamente; resultado sozinho não prova dolo.", "CP, art. 18, I, II e parágrafo único."),
      review("4. Quais são os requisitos legais básicos da tentativa?", "Execução iniciada, não consumação e circunstância alheia à vontade do agente.", "A pena é reduzida de um a dois terços, salvo disposição em contrário.", "CP, art. 14, II e parágrafo único."),
      review("5. Diferencie desistência voluntária de arrependimento eficaz.", "Na desistência o agente interrompe a execução; no arrependimento eficaz, depois de executar os atos, impede o resultado.", "Em ambos, responde pelos atos já praticados, conforme art. 15.", "CP, art. 15."),
      review("6. Qual efeito do erro de tipo essencial?", "Exclui o dolo, permitindo punição por culpa se houver previsão legal.", "Ele recai sobre elemento do tipo; não se confunde com erro sobre ilicitude.", "CP, art. 20, caput."),
      review("7. O desconhecimento da lei sempre isenta de pena?", "Não. O erro sobre ilicitude do fato só isenta se inevitável; se evitável, pode reduzir a pena.", "O art. 21 disciplina consciência potencial e evitabilidade do erro.", "CP, art. 21."),
      review("8. Quando se deve examinar concurso aparente antes de concurso de crimes?", "Quando uma mesma situação parece enquadrar-se em normas múltiplas e uma pode prevalecer ou absorver a outra.", "Verifique especialidade, subsidiariedade e consunção antes de somar infrações.", "CP, arts. 69 a 71 e estrutura dos tipos aplicáveis."),
    ],
    exercises: [
      exercise("penal-teoria-ex-1", "Um decreto municipal cria pena de detenção para conduta não prevista em lei. Qual princípio impede a punição penal com essa base?", "A", "CF, art. 5º, XXXIX; CP, art. 1º.", [
        { text: "Legalidade e anterioridade penal", why: "Crime e pena exigem lei anterior; decreto não cria tipo penal." }, { text: "Insignificância", why: "O enunciado não trata de ofensividade concreta ou bagatela." }, { text: "Individualização da pena", why: "A questão antecede a aplicação de uma pena validamente prevista." }, { text: "Presunção de inocência", why: "A falha apontada é ausência de lei penal, não o ônus probatório." },
      ]),
      exercise("penal-teoria-ex-2", "Uma pessoa responde por resultado ocorrido porque não socorreu terceiro. Para imputar o resultado por omissão imprópria, é necessário verificar:", "C", "CP, art. 13, § 2º.", [
        { text: "Apenas reprovação moral", why: "Dever moral isolado não cria posição penal de garantidor." }, { text: "Somente presença no local", why: "Presença não substitui dever jurídico e possibilidade de agir." }, { text: "Dever jurídico de agir, possibilidade concreta e nexo", why: "O art. 13, § 2º, exige posição de garantidor e dever de evitar o resultado." }, { text: "Responsabilidade automática pelo resultado", why: "O direito penal não admite imputação objetiva sem requisitos." },
      ]),
      exercise("penal-teoria-ex-3", "A execução de um crime é iniciada, mas a consumação é impedida por terceiro contra a vontade do agente. Em regra, há:", "D", "CP, art. 14, II e parágrafo único.", [
        { text: "Crime impossível", why: "Não há descrição de meio absolutamente ineficaz ou objeto absolutamente impróprio." }, { text: "Desistência voluntária", why: "O agente não interrompeu voluntariamente a execução." }, { text: "Arrependimento posterior", why: "Não há crime consumado sem violência reparado nos requisitos do art. 16." }, { text: "Tentativa", why: "Houve início de execução e não consumação por circunstância alheia à vontade." },
      ]),
      exercise("penal-teoria-ex-4", "O agente voluntariamente interrompe a execução antes de terminar os atos, podendo prosseguir. Qual instituto se examina?", "B", "CP, art. 15.", [
        { text: "Arrependimento eficaz", why: "Este pressupõe que o agente já tenha praticado os atos e depois impeça o resultado." }, { text: "Desistência voluntária", why: "A interrupção voluntária antes do esgotamento da execução corresponde ao art. 15." }, { text: "Tentativa perfeita", why: "A descrição indica interrupção pelo próprio agente, não fator externo." }, { text: "Arrependimento posterior", why: "Não se trata de reparação após crime consumado." },
      ]),
      exercise("penal-teoria-ex-5", "O agente desconhece que o objeto que leva pertence a outra pessoa e acredita justificadamente ser o seu. Qual instituto deve ser examinado primeiro?", "C", "CP, art. 20.", [
        { text: "Erro de proibição", why: "O fato não indica desconhecimento da ilicitude, mas erro sobre circunstância fática do tipo." }, { text: "Coação moral", why: "Não há ameaça ou pressão descrita." }, { text: "Erro de tipo", why: "O erro sobre fato constitutivo do tipo pode excluir dolo." }, { text: "Erro sobre pessoa", why: "O engano não recai sobre a identidade da vítima pretendida." },
      ]),
      exercise("penal-teoria-ex-6", "A lei posterior deixa de considerar criminosa a conduta praticada antes. Qual consequência penal geral decorre do art. 2º?", "A", "CF, art. 5º, XL; CP, art. 2º.", [
        { text: "A lei mais benéfica retroage e cessam execução e efeitos penais da condenação", why: "A abolitio criminis extingue efeitos penais nos termos do art. 2º." }, { text: "A lei só se aplica a fatos futuros", why: "Essa regra não se aplica à lei posterior benéfica." }, { text: "A lei retroage apenas antes da denúncia", why: "A retroatividade benéfica alcança inclusive condenação transitada em julgado." }, { text: "A condenação permanece por força da coisa julgada", why: "O art. 2º prevê cessação da execução e efeitos penais." },
      ]),
    ], sources: [cp, cf],
  },
  "penal-tipicidade-ilicitude-culpabilidade": {
    summary: ["Tipicidade pergunta se o fato corresponde ao tipo legal; ilicitude, se há justificante; culpabilidade, se cabe reprovação pessoal.", "Dolo/culpa pertencem à análise subjetiva do fato típico na estrutura finalista adotada didaticamente.", "Legítima defesa, estado de necessidade, estrito cumprimento do dever e exercício regular estão no art. 23.", "Erro de tipo afeta dolo; erro de proibição afeta potencial consciência da ilicitude.", "Imputabilidade, potencial consciência e exigibilidade orientam a culpabilidade."],
    sections: [
      section("penal-tipicidade-ilicitude-culpabilidade-topico-1", "1. Tipicidade: adequação formal e lesividade", ["Tipicidade formal é a correspondência entre conduta e descrição legal. Tipicidade material examina se a conduta atinge de modo relevante o bem jurídico, tema desenvolvido pela doutrina e jurisprudência. Para prova objetiva, identifique primeiro os elementos expressos do tipo e só então examine eventual insignificância segundo critérios jurídicos, sem inventar limite monetário fixo.", "O tipo pode conter elementos objetivos, normativos e subjetivos. Elemento normativo exige valoração jurídica ou cultural; especial fim de agir integra o tipo quando a lei o prevê. Não basta coincidência de palavras: todos os elementos devem estar demonstrados.", "Resultado e nexo são exigidos conforme a natureza do delito. O art. 13 regula causalidade dos crimes cujo resultado é necessário; a tentativa e os tipos formais seguem outras estruturas."], ["Compare fato com cada elemento legal.", "Diferencie elemento do tipo de circunstância da pena.", "Insignificância não é autorização para fixar um valor universal."], "Alguém recebe bem que sabe ser produto de crime, mas a questão pergunta sobre elemento subjetivo do tipo de receptação.", "A análise deve confrontar conhecimento e demais elementos legais, não apenas posse do objeto; consulte a descrição específica do art. 180 do CP."),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-2", "2. Ilicitude e causas de justificação", ["Tipicidade cria indício de ilicitude, mas a conduta pode estar autorizada pelo ordenamento. O art. 23 do CP prevê estado de necessidade, legítima defesa, estrito cumprimento de dever legal e exercício regular de direito. Cada justificante tem pressupostos próprios; não são etiquetas intercambiáveis.", "O parágrafo único do art. 23 prevê responsabilização pelo excesso doloso ou culposo. Mesmo quando uma situação começa legitimamente, a reação além do necessário pode gerar responsabilidade. Avalie atualidade, perigo, agressão, meios empregados e limites de cada instituto.", "O art. 24 define estado de necessidade em situação de perigo atual não provocado voluntariamente pelo agente, que não podia evitar de outro modo, para salvar direito próprio ou alheio, cujo sacrifício não era razoável exigir. O art. 25 define legítima defesa por uso moderado dos meios necessários para repelir injusta agressão atual ou iminente a direito próprio ou alheio."], ["Estado de necessidade: perigo atual e conflito de bens.", "Legítima defesa: agressão humana injusta, atual ou iminente.", "Necessidade/moderação e excesso precisam ser examinados."], "Diante de agressão já encerrada, a pessoa persegue o agressor horas depois e o agride para puni-lo.", "A atualidade/iminência da agressão e o propósito defensivo são requisitos da legítima defesa; vingança posterior não corresponde automaticamente ao art. 25."),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-3", "3. Estado de necessidade e legítima defesa: distinções", ["No estado de necessidade pode haver perigo provocado por fatos naturais ou humanos, com sacrifício de bem para salvar outro; na legítima defesa há agressão injusta humana. A lei especifica a atualidade do perigo e da agressão e a impossibilidade de evitar o risco de outro modo no art. 24.", "A legítima defesa exige meios necessários usados moderadamente. Não exige fuga como condição legal, mas a necessidade concreta dos meios e a moderação devem ser apreciadas. A proteção pode alcançar direito próprio ou alheio. A defesa putativa por erro é examinada no art. 20, § 1º, e não se confunde com justificação real.", "No estado de necessidade, o art. 24, § 2º, prevê redução de pena quando era razoável exigir o sacrifício do direito ameaçado. Essa consequência difere da exclusão da ilicitude do caput. Não transforme a regra em absolvição automática."], ["Necessidade: perigo; defesa: agressão injusta.", "A legítima defesa admite proteção de direito alheio.", "Necessidade excessiva pode gerar redução, não necessariamente exclusão (art. 24, § 2º)."], undefined, { headers: ["Critério", "Estado de necessidade", "Legítima defesa"], rows: [["Situação inicial", "Perigo atual.", "Agressão injusta atual ou iminente."], ["Origem", "Pode decorrer de fato natural ou humano.", "Agressão humana injusta."], ["Regra", "Salvar direito próprio ou alheio, sem outro meio e com proporcionalidade legal.", "Meios necessários, uso moderado."], ["Base", "CP, art. 24.", "CP, art. 25."]] }),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-4", "4. Estrito dever legal, exercício regular e consentimento", ["O estrito cumprimento do dever legal abrange atuação imposta por norma e dentro dos limites do dever. O exercício regular de direito protege conduta autorizada pelo ordenamento, também dentro de seus limites (CP, art. 23, III). Se há excesso, pode haver responsabilização.", "Consentimento do titular pode excluir tipicidade ou ilicitude conforme natureza do bem, disponibilidade e estrutura do tipo; não é causa geral expressa no art. 23. Não se presume consentimento válido quando o bem é indisponível ou quando a lei exige proteção penal independentemente da vontade.", "A autoridade pública não recebe autorização ilimitada pela função. Verifique competência, base legal, necessidade e limites do ato. A justificante deve ser demonstrada por fatos, e não pelo cargo do agente."], ["Estrito dever: dever jurídico específico e atuação dentro dos limites.", "Exercício regular: autorização jurídica para aquela conduta.", "Consentimento requer titularidade, capacidade, liberdade e disponibilidade do bem, conforme o caso."], "Profissional de saúde realiza procedimento consentido, indicado e tecnicamente adequado.", "O consentimento pode ser relevante, mas a análise depende da disponibilidade do bem, informação, capacidade e normas profissionais; não afasta automaticamente todo tipo penal."),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-5", "5. Imputabilidade e potencial consciência da ilicitude", ["Culpabilidade é juízo de reprovação pessoal na estrutura analítica do crime. A imputabilidade é capacidade de entender o caráter ilícito do fato e de determinar-se conforme esse entendimento, nos termos do art. 26. A inimputabilidade por doença mental exige os critérios legais ao tempo da ação ou omissão; diagnóstico isolado não basta.", "O art. 27 estabelece inimputabilidade penal dos menores de 18 anos, sujeitos à legislação especial. O art. 28, I, diz que emoção e paixão não excluem imputabilidade; embriaguez voluntária ou culposa também não a exclui (inciso II). Embriaguez completa por caso fortuito ou força maior pode isentar se retirou capacidade nos termos do § 1º; a incompleta pode reduzir a pena no § 2º.", "A potencial consciência da ilicitude integra análise de culpabilidade. Erro inevitável sobre ilicitude isenta; erro evitável reduz pena (art. 21). Diferencie isso do desconhecimento da lei, que por si só não justifica a conduta."], ["Art. 26: critério biopsicológico, com incapacidade no momento do fato.", "Menor de 18: inimputabilidade penal e sujeição a legislação especial.", "Embriaguez voluntária não exclui; fortuita completa pode excluir (art. 28)."], "A pessoa apresenta transtorno, mas no momento do fato conseguia compreender a ilicitude e agir conforme essa compreensão.", "O diagnóstico não determina sozinho inimputabilidade; a prova deve demonstrar o critério legal do art. 26 no momento da ação."),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-6", "6. Exigibilidade de conduta diversa e erro", ["Além de imputabilidade e consciência potencial da ilicitude, a culpabilidade examina se era exigível comportamento conforme o direito. A coação moral irresistível e a obediência hierárquica não manifestamente ilegal excluem culpabilidade do executor nos termos do art. 22; o autor da coação ou ordem responde pelo fato.", "A obediência hierárquica exige relação de direito público e ordem não manifestamente ilegal. Se a ilegalidade é evidente, o subordinado não fica protegido por cumprimento de ordem. A coação moral irresistível distingue-se da coação física absoluta, que pode afastar a própria conduta.", "O erro sobre pressupostos fáticos de justificante pode ser erro permissivo (art. 20, § 1º). Se plenamente justificado pelas circunstâncias, isenta; se deriva de culpa e há tipo culposo, pode haver punição culposa. Mantenha separados erro fático e erro sobre proibição."], ["Coação moral irresistível: exclui culpabilidade do coagido (art. 22).", "Ordem hierárquica: pública e não manifestamente ilegal.", "Erro permissivo: falsa percepção de situação fática justificante."], "Servidor recebe ordem manifestamente ilegal para praticar agressão sem urgência ou justificativa.", "O art. 22 não protege cumprimento de ordem manifestamente ilegal. O subordinado deve avaliar a evidência da ilegalidade e a possibilidade concreta de resistência."),
      section("penal-tipicidade-ilicitude-culpabilidade-topico-7", "7. Sequência analítica e erros frequentes", ["Para resolver, pergunte: há fato típico? Há causa de justificação? O agente é culpável? Qual é o efeito jurídico do erro ou da excludente? Essa sequência organiza a resposta sem confundir ausência de crime com isenção de pena ou redução.", "Excludentes de ilicitude afastam contrariedade ao direito, mas excesso pode ser punível. Excludentes de culpabilidade preservam, em regra, fato típico e ilícito, mas afastam reprovação pessoal. Erros podem repercutir em elemento diverso conforme incidam sobre fato típico ou ilicitude.", "A aula contém exemplos e exercícios autorais, não oficiais, e não esgota divergências doutrinárias. Permanece pendente de revisão jurídica e pedagógica; use o texto legal vigente e identifique a categoria exata cobrada."], ["Não chame toda excludente de “excludente de ilicitude”.", "Diferencie justificação real de justificante putativa.", "Analise excesso, requisitos e consequência legal."], "A prova informa agressão injusta atual e reação moderada com meios necessários.", "O enquadramento inicial é legítima defesa, art. 25; ainda se verificam necessidade, moderação e ausência de excesso."),
    ],
    reviewQuestions: [
      review("1. Que efeito uma justificante do art. 23 produz?", "Exclui a ilicitude quando seus requisitos estão presentes.", "A tipicidade pode permanecer; excesso doloso ou culposo é punível.", "CP, art. 23 e parágrafo único."),
      review("2. Qual diferença central entre estado de necessidade e legítima defesa?", "Necessidade parte de perigo atual; legítima defesa parte de agressão injusta atual ou iminente.", "A origem da situação e os requisitos de atuação são distintos.", "CP, arts. 24 e 25."),
      review("3. É necessário fugir para alegar legítima defesa?", "O art. 25 exige meios necessários usados moderadamente, mas não estabelece fuga como requisito geral.", "Necessidade e moderação são avaliadas concretamente.", "CP, art. 25."),
      review("4. Um diagnóstico médico basta para inimputabilidade?", "Não. É preciso satisfazer o critério legal de incapacidade ao tempo da ação ou omissão.", "O art. 26 requer incapacidade de entendimento ou autodeterminação nos termos legais.", "CP, art. 26."),
      review("5. Menores de 18 anos respondem penalmente pelo Código Penal?", "São penalmente inimputáveis e sujeitos à legislação especial.", "A regra constitucional e o art. 27 fixam o marco etário.", "CF, art. 228; CP, art. 27."),
      review("6. Embriaguez voluntária exclui imputabilidade?", "Não, em regra. O art. 28, II, afasta esse efeito; há disciplina própria para embriaguez fortuita ou por força maior.", "Examine origem, grau e capacidade conforme os parágrafos do art. 28.", "CP, art. 28."),
      review("7. Quando a obediência hierárquica pode excluir culpabilidade?", "Quando se cumpre ordem não manifestamente ilegal de superior hierárquico, em relação de direito público.", "A ordem evidentemente ilegal não é protegida pelo art. 22.", "CP, art. 22."),
      review("8. O que é erro permissivo?", "Erro sobre situação de fato que, se existisse, tornaria a ação legítima.", "O art. 20, § 1º, disciplina erro plenamente justificado e eventual modalidade culposa.", "CP, art. 20, § 1º."),
    ],
    exercises: [
      exercise("penal-tic-ex-1", "Uma pessoa reage a agressão injusta que está ocorrendo, usando moderadamente meio necessário para proteger terceiro. Qual justificante deve ser analisada?", "B", "CP, art. 25.", [
        { text: "Estado de necessidade", why: "O dado principal é agressão injusta humana, não conflito originado por perigo em geral." }, { text: "Legítima defesa", why: "O art. 25 admite proteção de direito próprio ou alheio contra agressão injusta atual ou iminente." }, { text: "Exercício regular de direito", why: "A situação descrita corresponde especificamente à defesa contra agressão." }, { text: "Coação moral irresistível", why: "Não há coação do agente por terceiro." },
      ]),
      exercise("penal-tic-ex-2", "A pessoa destrói bem de terceiro para afastar perigo atual, inevitável de outro modo, observados os requisitos legais. Qual dispositivo trata do estado de necessidade?", "D", "CP, art. 24.", [
        { text: "Art. 25", why: "Este dispositivo trata de legítima defesa contra agressão injusta." }, { text: "Art. 22", why: "Trata de coação e obediência hierárquica." }, { text: "Art. 28", why: "Trata de emoção, paixão e embriaguez." }, { text: "Art. 24", why: "Define estado de necessidade e seus pressupostos." },
      ]),
      exercise("penal-tic-ex-3", "Uma pessoa é diagnosticada com doença, mas a prova mostra capacidade plena de entendimento e autodeterminação no momento do fato. Qual conclusão é correta?", "A", "CP, art. 26.", [
        { text: "O diagnóstico isolado não demonstra inimputabilidade", why: "O art. 26 exige incapacidade legal ao tempo da ação ou omissão." }, { text: "A inimputabilidade decorre automaticamente do diagnóstico", why: "A lei exige critério biopsicológico, não apenas diagnóstico." }, { text: "O fato é atípico", why: "Imputabilidade se relaciona à culpabilidade, não substitui tipicidade." }, { text: "Toda pena deve ser reduzida", why: "Não há redução automática sem hipótese legal comprovada." },
      ]),
      exercise("penal-tic-ex-4", "O agente sofre coação moral irresistível para praticar a conduta. Em regra, quem responde pelo fato?", "C", "CP, art. 22.", [
        { text: "Ninguém, necessariamente", why: "O autor da coação pode responder pelo fato." }, { text: "Somente o coagido", why: "O art. 22 isenta o coagido quando irresistível." }, { text: "O autor da coação; o coagido fica isento nos termos legais", why: "É a consequência prevista no art. 22." }, { text: "O superior hierárquico sempre", why: "A hipótese não necessariamente envolve hierarquia." },
      ]),
      exercise("penal-tic-ex-5", "Uma ordem de superior em relação de direito público é manifestamente ilegal. O subordinado pode invocar obediência hierárquica do art. 22?", "B", "CP, art. 22.", [
        { text: "Sim, toda ordem hierárquica exclui culpabilidade", why: "O dispositivo limita a excludente a ordem não manifestamente ilegal." }, { text: "Não, a ordem deve não ser manifestamente ilegal", why: "A ilegalidade evidente exclui a proteção do art. 22." }, { text: "Sim, desde que haja vantagem", why: "Vantagem não é requisito da excludente." }, { text: "Não, porque o art. 22 só vale para particulares", why: "A obediência hierárquica se refere à hierarquia pública." },
      ]),
      exercise("penal-tic-ex-6", "A pessoa desconhece que a conduta é ilícita; o erro era inevitável nas circunstâncias. Qual efeito prevê o art. 21?", "D", "CP, art. 21.", [
        { text: "Exclusão automática da tipicidade", why: "Erro sobre ilicitude afeta culpabilidade, não necessariamente tipicidade." }, { text: "Apenas aumento de pena", why: "O art. 21 prevê isenção quando inevitável." }, { text: "Responsabilidade objetiva", why: "O erro não cria responsabilidade sem dolo/culpa." }, { text: "Isenção de pena por erro inevitável sobre a ilicitude", why: "É a consequência expressa no art. 21." },
      ]),
    ], sources: [cp, cf],
  },
  "penal-concurso-pessoas": {
    summary: ["O concurso exige pluralidade de agentes e contribuição juridicamente relevante.", "Cada agente responde na medida de sua culpabilidade (CP, art. 29).", "Ajuste ou auxílio sem início de tentativa, como regra, não é punível (art. 31).", "Circunstâncias pessoais não se comunicam, salvo quando elementares do crime (art. 30).", "Individualize coautoria, participação, dolo, contribuição e eventual cooperação dolosamente distinta."],
    sections: [
      section("penal-concurso-pessoas-topico-1", "1. Requisitos do concurso de pessoas", ["O art. 29 do CP adota, como regra, a teoria monista: quem concorre para o crime incide nas penas a ele cominadas, na medida de sua culpabilidade. A unidade do tipo não elimina a individualização da conduta e da pena de cada agente.", "A doutrina identifica requisitos como pluralidade de agentes e condutas, relevância causal da contribuição, vínculo subjetivo e identidade de infração. Em questão, presença no local, parentesco ou conhecimento posterior não substituem contribuição e dolo/culpa juridicamente exigidos.", "A participação de menor importância pode reduzir a pena de um sexto a um terço (art. 29, § 1º). A participação dolosamente distinta, se o concorrente quis participar de crime menos grave, segue § 2º: responde pelo crime que quis praticar, com aumento se era previsível o resultado mais grave."], ["Pluralidade + contribuição relevante + vínculo subjetivo + identidade de infração.", "A culpabilidade é individualizada.", "Ajuste prévio não basta sem execução ao menos tentada (art. 31)."], "Uma pessoa acompanha o grupo sem realizar ato de auxílio, instigação ou contribuição.", "O concurso não se presume por presença; devem ser demonstrados contribuição e vínculo subjetivo com o crime, conforme art. 29."),
      section("penal-concurso-pessoas-topico-2", "2. Coautoria e participação", ["Coautoria ocorre quando agentes realizam conjuntamente a conduta típica ou compartilham domínio funcional do fato segundo construção doutrinária; participação é contribuição acessória por induzimento, instigação ou auxílio. O art. 29 fornece regra legal de imputação e permite individualizar o peso da contribuição.", "Induzir é fazer nascer a ideia; instigar é reforçar decisão existente; auxiliar é prestar colaboração material. A distinção é didática e depende do caso. A contribuição deve anteceder ou acompanhar a execução e ser dolosa quanto à cooperação, salvo hipóteses culposas próprias previstas em lei.", "O partícipe pode receber pena reduzida por menor importância (art. 29, § 1º). O ajuste, determinação, instigação e auxílio não são puníveis se o crime não chega pelo menos a ser tentado, salvo disposição expressa (art. 31)."], ["Coautor: atuação conjunta na realização.", "Partícipe: contribuição moral ou material acessória.", "Atos preparatórios e participação dependem do início de tentativa, salvo exceção expressa."], "Uma pessoa fornece ferramenta sabendo e querendo facilitar crime que outro executará.", "A contribuição pode configurar auxílio material se houver vínculo subjetivo e relevância; a qualificação e pena dependem dos fatos e do art. 29."),
      section("penal-concurso-pessoas-topico-3", "3. Autoria mediata e atuação por intermédio de terceiro", ["Na autoria mediata, alguém realiza o delito por meio de pessoa que funciona como instrumento, por exemplo em hipóteses de erro ou coação, conforme a construção dogmática. É diferente de participação, pois o autor mediato controla a realização por intermédio de outro.", "Se o executor é plenamente responsável e atua com autonomia, pode haver coautoria ou participação, não autoria mediata. Examine quem tinha domínio da decisão e da execução, sem tratar superior hierárquico como autor automaticamente.", "A autoria colateral aparece quando agentes agem independentemente, sem vínculo subjetivo, e produzem ou tentam produzir o mesmo resultado. Nesse caso, não se atribui concurso apenas porque as condutas convergiram; cada contribuição é examinada individualmente e a prova causal importa."], ["Autoria mediata: realização por instrumento, com controle do autor mediato.", "Coautoria pressupõe atuação comum e vínculo subjetivo.", "Autoria colateral independente não equivale a concurso de agentes."], "Duas pessoas, sem conhecer a ação uma da outra, disparam contra a mesma vítima no mesmo momento.", "Sem vínculo subjetivo não se afirma coautoria automaticamente. Deve-se apurar nexo causal e imputação individual para cada disparo."),
      section("penal-concurso-pessoas-topico-4", "4. Circunstâncias e condições pessoais", ["O art. 30 prevê que não se comunicam as circunstâncias e condições de caráter pessoal, salvo quando elementares do crime. Elementar é dado indispensável à configuração do tipo; circunstância modifica aspectos do delito sem ser essencial ao tipo básico.", "As circunstâncias objetivas podem comunicar-se quando conhecidas e abrangidas pelo vínculo subjetivo, conforme a análise doutrinária do caso. Circunstância pessoal, como reincidência ou motivo individual, não passa automaticamente a outro agente.", "O concurso em crimes próprios exige atenção: qualidade especial do sujeito pode ser elementar e comunicar-se ao concorrente que não a possui, desde que ele a conheça e participe com o elemento subjetivo correspondente. A imputação sempre precisa ser individualizada."], ["Regra: circunstância pessoal não se comunica.", "Exceção: elemento pessoal que integra o tipo, com conhecimento do concorrente.", "Não confunda elementar do crime próprio e agravante pessoal."], "Pessoa sem qualidade funcional especial auxilia agente que pratica crime próprio, conhecendo a condição que integra o tipo.", "O art. 30 permite comunicação de elementar pessoal, desde que seja elementar e esteja abrangida pelo conhecimento e vínculo subjetivo do concorrente."),
      section("penal-concurso-pessoas-topico-5", "5. Concurso em crimes omissivos e culposos", ["O concurso pode ocorrer em delitos omissivos quando mais de um garantidor viola dever de agir com contribuição juridicamente relevante. Cada pessoa deve ter dever e possibilidade de evitar o resultado; não se transfere a posição de garantidor por mera relação social.", "Crimes culposos admitem coautoria segundo entendimento doutrinário quando agentes atuam conjuntamente violando dever objetivo de cuidado e contribuem para resultado previsível. Participação em crime culposo é objeto de controvérsia; para evitar generalização, a aula concentra a análise no texto legal e na imputação individual.", "A responsabilidade por resultado culposo exige previsibilidade e nexo. O concurso não substitui análise do dever de cuidado de cada agente nem transforma falha organizacional em culpa coletiva automática."], ["A posição de garantidor é individual.", "Individualize dever de cuidado, contribuição, previsibilidade e nexo.", "Evite imputação coletiva sem análise da conduta de cada pessoa."], "Dois profissionais têm deveres legais de vigilância e ambos deixam de adotar medidas que poderiam impedir o resultado.", "A eventual imputação exige apurar dever e possibilidade de agir de cada um, contribuição causal e modalidade subjetiva; o vínculo profissional isolado não basta."),
      section("penal-concurso-pessoas-topico-6", "6. Cooperação dolosamente distinta e participação menor", ["O art. 29, § 2º, protege o concorrente que quis participar de crime menos grave: responde por esse crime; se o resultado mais grave era previsível, a pena pode ser aumentada até metade. A regra exige identificar plano subjetivo e previsibilidade, não se aplica automaticamente a toda divergência entre agentes.", "Participação de menor importância (art. 29, § 1º) considera o peso da contribuição no caso e autoriza redução de um sexto a um terço. Não confunda participação acessória com participação de menor importância: toda participação é acessória, mas nem toda tem menor relevância.", "O ajuste do art. 31 não é punível se não há tentativa, salvo disposição expressa. Alguns delitos autônomos criminalizam associação ou atos preparatórios específicos; então a tipificação especial deve ser analisada separadamente."], ["Quis crime menos grave: responde por ele; previsibilidade pode elevar pena até metade.", "Menor importância: redução facultativa de 1/6 a 1/3.", "Verifique se lei especial tipifica preparação/associação autonomamente."], "Um agente aceita participar de subtração sem violência; outro, inesperadamente, pratica violência grave.", "Analise o art. 29, § 2º: intenção do primeiro quanto ao crime menos grave e previsibilidade do resultado mais grave, sem automatismo."),
      section("penal-concurso-pessoas-topico-7", "7. Método para individualizar a responsabilidade", ["Faça uma matriz por pessoa: o que fez, quando, com qual intenção, qual contribuição causal e qual circunstância conhecia. Depois verifique se houve tentativa, tipo comum ou próprio, circunstâncias comunicáveis e regra de pena.", "O art. 29 não cria responsabilidade por associação. Nem hierarquia, parentesco, profissão ou presença provam dolo. A coautoria e a participação devem ser fundamentadas em fatos e vínculo subjetivo.", "Os exemplos e exercícios são autorais e didáticos, não questões oficiais da OAB. O tema comporta construções doutrinárias e jurisprudenciais; conteúdo permanece pendente de revisão jurídica e pedagógica."], ["Individualize conduta e elemento subjetivo.", "Distinga execução conjunta e contribuição acessória.", "Só depois aplique regra de comunicação e pena."], "Uma pessoa vende objeto após o crime sem ter conhecimento da origem ilícita.", "A relação posterior não prova participação no crime antecedente; examine dolo, momento e tipo eventualmente aplicável, sem presumir concurso."),
    ],
    reviewQuestions: [
      review("1. Qual regra geral de imputação está no art. 29?", "Quem concorre para o crime responde pelas penas cominadas, na medida de sua culpabilidade.", "A unidade da infração não elimina individualização da contribuição e da pena.", "CP, art. 29."),
      review("2. Presença no local basta para concurso de pessoas?", "Não. É necessário demonstrar contribuição e vínculo subjetivo, além dos demais requisitos.", "Responsabilidade penal não pode decorrer de associação ou proximidade apenas.", "CP, art. 29."),
      review("3. O que caracteriza participação de menor importância?", "Contribuição acessória de menor relevo no caso, que pode justificar redução de um sexto a um terço.", "É causa de diminuição facultativa do art. 29, § 1º.", "CP, art. 29, § 1º."),
      review("4. Quando circunstância pessoal pode comunicar-se ao concorrente?", "Quando constituir elementar do crime, conforme art. 30, e estiver abrangida pelo conhecimento/vínculo subjetivo do agente.", "Circunstâncias pessoais em geral não se comunicam.", "CP, art. 30."),
      review("5. O ajuste para cometer crime é punível se nada chega à tentativa?", "Em regra não, salvo disposição expressa em contrário.", "O art. 31 menciona ajuste, determinação, instigação e auxílio.", "CP, art. 31."),
      review("6. O que ocorre na cooperação dolosamente distinta?", "O concorrente que quis participar de crime menos grave responde por ele; se previsível o resultado mais grave, pode haver aumento até metade.", "A intenção e previsibilidade devem ser provadas individualmente.", "CP, art. 29, § 2º."),
      review("7. Coautoria e participação são iguais?", "Não. Coautoria envolve realização conjunta; participação é contribuição acessória moral ou material.", "Ambas podem atrair art. 29, mas a natureza e relevância da contribuição diferem.", "CP, art. 29."),
      review("8. Como analisar autoria colateral?", "Verifique se os agentes atuaram independentemente, sem vínculo subjetivo, e apure causalidade e responsabilidade de cada um.", "A convergência de resultados não cria concurso sem liame subjetivo.", "CP, art. 29; art. 13 para causalidade."),
    ],
    exercises: [
      exercise("penal-concurso-ex-1", "Uma pessoa apenas presencia a execução e não contribui, instiga ou auxilia. Qual afirmação é correta?", "C", "CP, art. 29.", [
        { text: "Responde sempre como coautora", why: "Presença isolada não demonstra contribuição nem vínculo subjetivo." }, { text: "Responde por associação", why: "O enunciado não descreve tipo autônomo de associação." }, { text: "A presença, sozinha, não basta para concurso", why: "É necessário demonstrar contribuição juridicamente relevante e liame subjetivo." }, { text: "É necessariamente partícipe moral", why: "Não há instigação ou induzimento narrado." },
      ]),
      exercise("penal-concurso-ex-2", "Um agente presta auxílio de pequena relevância a crime que sabia que seria praticado. Qual previsão pode reduzir a pena?", "A", "CP, art. 29, § 1º.", [
        { text: "Participação de menor importância", why: "O § 1º permite redução de um sexto a um terço se a participação for de menor importância." }, { text: "Erro de tipo", why: "O enunciado afirma conhecimento do crime." }, { text: "Desistência voluntária", why: "Não descreve interrupção da execução pelo agente." }, { text: "Arrependimento posterior", why: "Não há reparação de dano ou restituição nos requisitos do art. 16." },
      ]),
      exercise("penal-concurso-ex-3", "Uma condição pessoal integra o próprio tipo penal e o concorrente conhece essa condição. O art. 30 prevê que ela:", "D", "CP, art. 30.", [
        { text: "Nunca se comunica", why: "O artigo contém exceção para elementares do crime." }, { text: "Comunica-se sempre, ainda que desconhecida", why: "A imputação subjetiva não pode ser presumida." }, { text: "Transforma o concorrente em autor material", why: "Comunicação de elementar não define modalidade de autoria." }, { text: "Pode comunicar-se por ser elementar, observados os requisitos subjetivos", why: "O art. 30 excepciona elementares das circunstâncias pessoais não comunicáveis." },
      ]),
      exercise("penal-concurso-ex-4", "Agente quis participar de delito menos grave; o resultado mais grave era previsível. Qual regra se examina?", "B", "CP, art. 29, § 2º.", [
        { text: "Responsabilidade por todo resultado sem limite", why: "O Código individualiza a intenção e prevê regra específica." }, { text: "Cooperação dolosamente distinta", why: "O agente responde pelo que quis; previsibilidade pode elevar a pena até metade." }, { text: "Crime impossível", why: "O enunciado não trata de impossibilidade de consumação." }, { text: "Participação de menor importância", why: "A questão trata do desvio subjetivo para crime mais grave." },
      ]),
      exercise("penal-concurso-ex-5", "Há acordo para cometer delito, mas os agentes não iniciam a execução e a lei não prevê crime autônomo de associação. Como regra, o acordo isolado:", "C", "CP, art. 31.", [
        { text: "É sempre punível como tentativa", why: "Não houve início de execução." }, { text: "É coautoria consumada", why: "O art. 31 afasta punição de ajuste sem tentativa, salvo exceção legal." }, { text: "Não é punível por si só, salvo previsão expressa", why: "É a regra do art. 31." }, { text: "Gera pena reduzida", why: "Não se trata de crime tentado com pena a reduzir." },
      ]),
      exercise("penal-concurso-ex-6", "Dois agentes atuam sem saber um do outro e causam resultado simultâneo. Qual cuidado é correto?", "A", "CP, arts. 13 e 29.", [
        { text: "Não presumir concurso; apurar nexo e imputação de cada um", why: "Sem vínculo subjetivo, a autoria colateral demanda análise causal individual." }, { text: "Aplicar coautoria automaticamente", why: "A atuação independente afasta liame subjetivo presumido." }, { text: "Imputar resultado a ambos sem prova", why: "Causalidade e contribuição devem ser demonstradas." }, { text: "Extinguir o crime", why: "A independência não exclui necessariamente responsabilidade individual." },
      ]),
    ], sources: [cp, cf],
  },
  "penal-penas": {
    summary: ["As penas previstas no CP são privativas de liberdade, restritivas de direitos e multa.", "Individualização observa lei, circunstâncias judiciais e fundamentação concreta.", "Substituição por restritiva de direitos exige requisitos do art. 44.", "Regimes iniciais seguem art. 33 e circunstâncias legais, não apenas gravidade abstrata.", "Multa é calculada em dias-multa, com valor unitário conforme capacidade econômica."],
    sections: [
      section("penal-penas-topico-1", "1. Espécies de pena e princípios", ["O art. 32 do CP enumera penas privativas de liberdade, restritivas de direitos e multa. A Constituição veda penas de morte, salvo guerra declarada, perpétuas, trabalhos forçados, banimento e cruéis (art. 5º, XLVII), além de assegurar individualização (XLVI).", "A pena pressupõe condenação válida e deve observar legalidade, culpabilidade, proporcionalidade e individualização. A execução segue a Lei de Execução Penal, sem que a pena se confunda com medida de segurança.", "A escolha da espécie e quantidade exige base legal. Gravidade abstrata do tipo não basta para aumentar pena-base sem circunstâncias concretas; cada fase da dosimetria tem função própria."], ["Espécies: art. 32 do CP.", "Limites constitucionais: CF, art. 5º, XLVII.", "Individualização: legislativa, judicial e executória."], "Uma alternativa afirma que a reincidência permite pena perpétua.", "A Constituição proíbe pena de caráter perpétuo (art. 5º, XLVII, b); reincidência não afasta garantias constitucionais."),
      section("penal-penas-topico-2", "2. Dosimetria: sistema trifásico", ["O art. 68 prevê cálculo em três fases: pena-base segundo circunstâncias judiciais do art. 59; agravantes e atenuantes; causas de aumento e diminuição. A ordem importa e evita duplicar fator valorado em mais de uma etapa.", "Na primeira fase, o juiz avalia culpabilidade, antecedentes, conduta social, personalidade, motivos, circunstâncias, consequências e comportamento da vítima, fixando pena necessária e suficiente. A fundamentação deve indicar dados concretos e não pode usar elementar do tipo como agravante disfarçada.", "Na segunda fase incidem agravantes dos arts. 61 e seguintes e atenuantes dos arts. 65 e seguintes. Na terceira, aplicam-se frações de causas especiais. A pena final deve permanecer dentro dos limites legais, com análise de concurso e continuidade quando pertinente."], ["Fase 1: art. 59, pena-base.", "Fase 2: agravantes e atenuantes.", "Fase 3: causas de aumento e diminuição."], "Na primeira fase, o julgador usa como fundamento apenas o fato que já constitui elemento do crime.", "O mesmo dado não deve ser valorado em duplicidade; a pena-base exige circunstância judicial concreta além dos elementos inerentes ao tipo."),
      section("penal-penas-topico-3", "3. Regimes e execução da pena privativa", ["O art. 33 prevê reclusão e detenção e disciplina regimes fechado, semiaberto e aberto. O regime inicial considera quantidade da pena, reincidência e circunstâncias judiciais, com fundamentação. A detenção começa, em regra, em semiaberto ou aberto, ressalvada transferência legalmente cabível.", "A fixação do regime não pode repousar apenas na gravidade abstrata do delito; deve observar parâmetros legais e fundamentação concreta. Progressão e demais regras executórias pertencem à Lei de Execução Penal e dependem de requisitos próprios, que podem mudar por alterações legislativas.", "Regime inicial e regime durante execução são momentos distintos. A resposta da prova deve identificar qual decisão está em análise e qual lei rege o caso no tempo."], ["Regime inicial: CP, art. 33, §§ 2º e 3º.", "Regime de cumprimento pode progredir conforme LEP.", "Quantidade da pena não é o único critério."], "Pessoa recebe pena em regime inicial e pergunta se isso fixa todo o cumprimento até o final.", "Não. Regime inicial é determinado na sentença; execução pode seguir regras de progressão e regressão previstas na LEP."),
      section("penal-penas-topico-4", "4. Substituição e suspensão condicional", ["Pena privativa pode ser substituída por restritivas de direitos quando presentes requisitos do art. 44: pena aplicada dentro dos limites legais, crime sem violência ou grave ameaça quando exigido, condições pessoais e suficiência da substituição. O inciso I contém regra própria para crime culposo, independentemente da pena.", "As penas restritivas estão no art. 43, incluindo prestação pecuniária, perda de bens e valores, prestação de serviços, interdição temporária e limitação de fim de semana. O art. 44 também regula quantidade de substitutas e conversão em privativa se houver descumprimento injustificado.", "Suspensão condicional da pena (sursis) está nos arts. 77 a 82 e tem requisitos próprios, inclusive subsidiariedade à substituição do art. 44. Não se deve confundir suspensão da execução com substituição da espécie da pena."], ["Substituição: art. 44; avalie crime, pena e requisitos subjetivos.", "Sursis: suspende execução sob condições; arts. 77-82.", "São institutos diferentes e não se presumem pela primariedade."], "Réu primário pede substituição apenas porque a pena é curta, sem que se examine violência ou demais requisitos.", "A duração, isoladamente, não basta. É necessário aplicar todos os requisitos do art. 44 e fundamentar suficiência da substituição."),
      section("penal-penas-topico-5", "5. Pena de multa e cálculo", ["A multa é calculada em dias-multa (CP, arts. 49 a 52). O número de dias é definido conforme limites legais e circunstâncias do crime; o valor de cada dia considera principalmente a situação econômica do condenado. São duas etapas diferentes.", "A multa é atualizada e executada conforme legislação penal e processual vigente. O art. 51 define sua natureza de dívida de valor para execução; isso não apaga sua natureza de sanção penal. A inadimplência não autoriza conversão automática em prisão, vedada pelo sistema.", "Em concurso de crimes, a multa segue regras próprias (art. 72). A fixação deve respeitar limites e motivação; não se escolhe valor unitário apenas pelo prejuízo da vítima."], ["Dias-multa: quantidade ligada à sanção e circunstâncias.", "Valor unitário: capacidade econômica.", "Multa não se converte automaticamente em prisão."], "Condenado tem renda elevada, mas a sentença fixa valor unitário mínimo sem justificar.", "O valor unitário deve considerar situação econômica conforme art. 60; a fundamentação precisa relacionar o valor à capacidade de pagamento."),
      section("penal-penas-topico-6", "6. Concurso de crimes e efeitos da condenação", ["No concurso material (art. 69), várias ações ou omissões produzem dois ou mais crimes e as penas são aplicadas cumulativamente. No concurso formal (art. 70), uma ação ou omissão produz dois ou mais crimes, aplicando-se regra de exasperação, com ressalva do concurso formal impróprio quando há desígnios autônomos.", "Crime continuado (art. 71) considera crimes da mesma espécie, praticados em condições semelhantes de tempo, lugar e modo, como continuação do primeiro; requisitos não se reduzem a repetição. O juiz aplica uma pena com aumento legal. Distinga concurso de crimes de concurso aparente de normas.", "Efeitos da condenação podem ser penais e extrapenais (arts. 91 e 92), mas alguns não são automáticos e exigem declaração motivada. A perda de cargo, função ou mandato, por exemplo, depende das hipóteses e requisitos do art. 92."], ["Material: pluralidade de condutas; soma.", "Formal: uma conduta; regra de exasperação, salvo desígnios autônomos.", "Continuidade delitiva: requisitos do art. 71 e aumento."], undefined, { headers: ["Instituto", "Número de condutas", "Regra resumida"], rows: [["Concurso material", "Mais de uma.", "Cumulam-se penas (art. 69)."], ["Concurso formal próprio", "Uma.", "Aplica-se exasperação do art. 70."], ["Crime continuado", "Mais de uma em condições semelhantes.", "Considera-se continuação (art. 71)."]] }),
      section("penal-penas-topico-7", "7. Roteiro de prova sobre penas", ["Identifique primeiro a espécie e a pena cominada; depois separe pena abstrata e aplicada; percorra as três fases do art. 68; analise regime inicial, substituição, sursis e multa em perguntas distintas.", "Não use antecedentes para agravar sem observar conceito legal e fundamentação. Não confunda agravante, qualificadora, causa de aumento e circunstância judicial. Evite contar o mesmo fato em mais de uma fase.", "A legislação de execução e os limites de pena podem ser alterados. Exercícios desta aula são autorais, não oficiais da OAB; conteúdo ainda depende de revisão jurídica e pedagógica."], ["Dosimetria tem ordem legal.", "Substituição depende de requisitos cumulativos.", "Regime, multa e efeitos são análises autônomas."], "Uma sentença aumenta pena-base e depois usa o mesmo fato como agravante.", "Verifique bis in idem e a função de cada fase da dosimetria; circunstância não pode ser valorada duas vezes sem base distinta."),
    ],
    reviewQuestions: [
      review("1. Quais espécies de pena constam do art. 32 do CP?", "Privativas de liberdade, restritivas de direitos e multa.", "A Constituição ainda estabelece penas vedadas.", "CP, art. 32; CF, art. 5º, XLVII."),
      review("2. Quais são as fases da dosimetria?", "Pena-base; agravantes e atenuantes; causas de aumento e diminuição.", "É o sistema trifásico do art. 68.", "CP, arts. 59 e 68."),
      review("3. O que se avalia na primeira fase?", "As circunstâncias judiciais do art. 59, com fundamentação concreta.", "Não se deve usar elementar do tipo em duplicidade para agravar a base.", "CP, art. 59."),
      review("4. A gravidade abstrata do delito basta para impor regime mais severo?", "Não. O regime deve observar parâmetros legais e fundamentação concreta.", "O art. 33, § 3º, remete às circunstâncias judiciais.", "CP, art. 33, §§ 2º e 3º."),
      review("5. Primariedade garante substituição por restritiva?", "Não. É necessário preencher os requisitos do art. 44.", "A análise inclui natureza do crime, pena e suficiência da medida.", "CP, arts. 43 e 44."),
      review("6. Como se calcula a multa?", "Em dias-multa; quantidade e valor unitário são fixados segundo critérios legais distintos.", "A situação econômica influencia o valor do dia-multa.", "CP, arts. 49, 50 e 60."),
      review("7. O que distingue concurso material e formal?", "Material envolve pluralidade de condutas; formal, uma conduta que gera vários crimes.", "As regras de aplicação da pena diferem nos arts. 69 e 70.", "CP, arts. 69 e 70."),
      review("8. A perda de cargo como efeito da condenação é sempre automática?", "Não. O art. 92 prevê hipóteses e, em regra, exige declaração motivada.", "Diferencie efeito automático de efeito que depende de fundamentação judicial.", "CP, arts. 91 e 92."),
    ],
    exercises: [
      exercise("penal-penas-ex-1", "Qual é a ordem geral da dosimetria prevista pelo Código Penal?", "A", "CP, art. 68.", [
        { text: "Pena-base; agravantes/atenuantes; causas de aumento/diminuição", why: "Essa é a sequência trifásica do art. 68." }, { text: "Regime; multa; pena-base", why: "Regime não antecede a fixação da pena." }, { text: "Agravantes; pena-base; substituição", why: "Inverte as duas primeiras fases e omite causas." }, { text: "Apenas pena-base e regime", why: "O sistema tem três fases." },
      ]),
      exercise("penal-penas-ex-2", "O art. 32 do CP prevê como espécies de pena:", "C", "CP, art. 32.", [
        { text: "Prisão perpétua e multa", why: "Pena perpétua é constitucionalmente vedada." }, { text: "Advertência, suspensão e prisão civil", why: "Não corresponde ao rol do art. 32." }, { text: "Privativas de liberdade, restritivas de direitos e multa", why: "É o rol legal do art. 32." }, { text: "Somente reclusão e detenção", why: "O artigo prevê outras espécies penais." },
      ]),
      exercise("penal-penas-ex-3", "A substituição da pena privativa de liberdade por restritiva de direitos depende:", "D", "CP, art. 44.", [
        { text: "Apenas da vontade do condenado", why: "A substituição depende dos requisitos legais." }, { text: "Somente de pena inferior a um ano", why: "O art. 44 estabelece conjunto mais amplo de critérios." }, { text: "Sempre que não houver reincidência", why: "Primariedade isolada não basta." }, { text: "Dos requisitos objetivos e subjetivos do art. 44", why: "A lei exige análise conjunta e suficiência da substituição." },
      ]),
      exercise("penal-penas-ex-4", "Qual regra distingue concurso material e formal?", "B", "CP, arts. 69 e 70.", [
        { text: "Ambos sempre somam penas", why: "O concurso formal tem regra própria de exasperação." }, { text: "Material: mais de uma conduta; formal: uma conduta produz vários crimes", why: "Essa é a distinção estrutural dos arts. 69 e 70." }, { text: "Material: uma conduta; formal: várias", why: "A alternativa inverte os institutos." }, { text: "São sinônimos", why: "Possuem requisitos e consequências diferentes." },
      ]),
      exercise("penal-penas-ex-5", "Em regra, a multa penal é fixada em:", "C", "CP, arts. 49 e 60.", [
        { text: "Valor único baseado apenas no dano", why: "O sistema usa dias-multa e critérios próprios." }, { text: "Horas de serviço", why: "Isso se relaciona a prestação de serviços, não multa." }, { text: "Dias-multa, com valor unitário considerado conforme situação econômica", why: "O CP separa quantidade de dias e valor de cada unidade." }, { text: "Percentual fixo do salário mínimo para todos", why: "A fixação segue limites legais e situação econômica." },
      ]),
      exercise("penal-penas-ex-6", "Uma sentença usa o mesmo dado fático para aumentar a pena-base e também como agravante. Qual problema deve ser examinado?", "A", "CP, arts. 59, 61 e 68.", [
        { text: "Bis in idem na dosimetria", why: "O mesmo fato não deve ser valorado duas vezes sem fundamento independente." }, { text: "Crime continuado", why: "A questão trata de dupla valoração, não pluralidade de crimes semelhantes." }, { text: "Abolitio criminis", why: "Não houve alteração que deixou de considerar crime a conduta." }, { text: "Erro de tipo", why: "O problema está na aplicação da pena, não na percepção do fato." },
      ]),
    ], sources: [cp, cf],
  },
  "penal-crimes-especie": {
    summary: ["Leia o tipo vigente elemento por elemento e determine tempo do crime e lei aplicável.", "Furto exige subtração de coisa alheia móvel; roubo acrescenta violência ou grave ameaça.", "Estelionato envolve obtenção de vantagem ilícita mediante fraude e prejuízo alheio.", "Nos crimes de drogas, diferencie art. 28 e art. 33 da Lei 11.343 pelos fatos e destinação.", "Consulte alterações recentes do CP e não memorize penas sem conferir o texto compilado."],
    sections: [
      section("penal-crimes-especie-topico-1", "1. Método de leitura dos crimes em espécie", ["Comece pelo verbo nuclear e identifique sujeito ativo/passivo, objeto material, elemento subjetivo, resultado e circunstâncias. Compare todos os fatos narrados com o texto vigente. Em tipos com finalidade especial, a intenção específica é elemento do crime.", "A lei penal aplicável no tempo é determinada pelo momento da ação ou omissão (CP, art. 4º), ainda que o resultado ocorra depois. Lei posterior mais benéfica retroage (art. 2º); lei temporária/excepcional pode continuar aplicável ao fato durante sua vigência (art. 3º).", "O portal do Planalto sinaliza alterações legislativas recentes no Código Penal, inclusive em dispositivos de crimes patrimoniais. Antes de responder sobre pena ou qualificadora, abra a redação compilada atual e confira a lei vigente à época do fato."], ["Tipo penal + fatos provados + lei no tempo.", "Não acrescente qualificadora não descrita.", "Atenção a alterações recentes: sempre confira texto vigente e regra intertemporal."], "O enunciado narra subtração sem dizer se houve violência ou fraude.", "Não se pode completar fato ausente; deve-se analisar somente os elementos provados e, se necessário, indicar que a classificação depende do dado faltante."),
      section("penal-crimes-especie-topico-2", "2. Crimes contra a pessoa: homicídio e lesão", ["O homicídio simples (CP, art. 121) consiste em matar alguém; qualificadoras e causas de aumento estão no próprio artigo. A Lei 14.994/2024 inseriu feminicídio como tipo autônomo no art. 121-A, com elementos próprios relacionados às razões da condição do sexo feminino. A redação atual deve ser consultada, sem reutilizar versões anteriores que tratavam feminicídio como qualificadora do art. 121.", "Lesão corporal (art. 129) exige ofensa à integridade corporal ou saúde; o artigo diferencia formas leves, graves, gravíssimas e seguida de morte, com critérios legais. O resultado e o elemento subjetivo determinam o enquadramento; morte resultante de lesão dolosa sem intenção de matar não é automaticamente homicídio.", "Dolo eventual, culpa e preterdolo devem ser analisados conforme os arts. 18 e 19. A qualificadora ou causa de aumento exige fato e requisito específicos; gravidade intuitiva não substitui descrição legal."], ["Art. 121-A: tipo autônomo de feminicídio após Lei 14.994/2024.", "Art. 129: lesão e resultados qualificados têm critérios próprios.", "Diferencie intenção de matar, dolo de lesionar e resultado culposo."], "A conduta causa lesão e a morte ocorre sem intenção ou assunção do risco de matar.", "A classificação depende do dolo inicial, previsibilidade/culpa no resultado e art. 19; não se deduz homicídio doloso apenas da morte."),
      section("penal-crimes-especie-topico-3", "3. Crimes patrimoniais: furto, roubo e estelionato", ["Furto é subtrair, para si ou para outrem, coisa alheia móvel (CP, art. 155). Roubo (art. 157) também envolve subtração, mas com violência, grave ameaça ou redução da vítima à impossibilidade de resistência. A distinção principal está no meio empregado, não apenas no valor do bem.", "Estelionato (art. 171) envolve obter, para si ou para outrem, vantagem ilícita em prejuízo alheio, induzindo ou mantendo alguém em erro por artifício, ardil ou outro meio fraudulento. Na fraude eletrônica, consulte a redação vigente e as alterações recentes. Apropriação indébita (art. 168) parte de posse ou detenção inicialmente legítima e posterior inversão do ânimo.", "O momento de consumação, tentativa e majorantes depende da descrição legal e dos fatos. O CP sofreu alterações legislativas recentes em furtos e outros delitos patrimoniais; não reproduza pena antiga sem conferir o texto compilado."], ["Furto: subtração sem violência/grave ameaça à pessoa.", "Roubo: subtração com violência, grave ameaça ou impossibilidade de resistência.", "Estelionato: fraude induz vítima em erro para obter vantagem."], undefined, { headers: ["Tipo", "Conduta central", "Ponto de distinção"], rows: [["Furto", "Subtrair coisa alheia móvel.", "Art. 155; sem violência pessoal como elemento do tipo básico."], ["Roubo", "Subtrair com violência/grave ameaça ou meio legalmente previsto.", "Art. 157; violência ou ameaça contra pessoa."], ["Estelionato", "Fraude que induz/mantém em erro para vantagem ilícita.", "Art. 171; consentimento é obtido mediante fraude."]] }),
      section("penal-crimes-especie-topico-4", "4. Crimes contra a Administração e fé pública", ["Peculato (art. 312) envolve apropriação, desvio ou subtração de bem móvel por funcionário público em razão do cargo; o tipo tem modalidades e requisitos. Concussão (art. 316) é exigir vantagem indevida em razão da função; corrupção passiva (art. 317) é solicitar, receber ou aceitar promessa de vantagem indevida. Verbos e momento consumativo diferenciam os tipos.", "Prevaricação (art. 319) exige retardar, deixar de praticar ou praticar indevidamente ato de ofício para satisfazer interesse ou sentimento pessoal. A mera ilegalidade administrativa não basta sem elemento subjetivo específico. O conceito penal de funcionário público está no art. 327 e pode alcançar quem exerce função pública transitoriamente ou sem remuneração.", "Crimes de fé pública como falsidade documental (arts. 297 a 304) protegem confiança em documentos e sinais. Compare documento público/particular, falsidade material/ideológica e uso, sem presumir que toda irregularidade documental seja crime."], ["Concussão: exigir vantagem.", "Corrupção passiva: solicitar/receber/aceitar promessa.", "Prevaricação exige finalidade específica do art. 319.", "Confira conceito penal de funcionário público no art. 327."], "Agente público retarda ato de ofício apenas por desorganização, sem objetivo de satisfazer interesse ou sentimento pessoal.", "O tipo de prevaricação exige elemento subjetivo especial; atraso administrativo isolado não permite concluir pelo crime do art. 319."),
      section("penal-crimes-especie-topico-5", "5. Crimes de drogas: distinguir posse e tráfico", ["A Lei 11.343/2006 diferencia condutas do art. 28, relacionadas a porte para consumo pessoal, e do art. 33, que descreve tráfico em múltiplos verbos. A classificação não depende só da quantidade: natureza e quantidade da substância, local, condições da ação, circunstâncias sociais e pessoais e conduta devem ser consideradas conforme art. 28, § 2º.", "A lei tipifica associação para o tráfico (art. 35) e outras condutas autônomas. Associação exige estabilidade e permanência segundo entendimento consolidado, mas uma avaliação jurisprudencial específica deve ser feita na fonte oficial; nesta aula não se afirma resultado de precedente sem referência.", "A Lei 11.343 contém procedimento e causas de aumento/diminuição próprios. O § 4º do art. 33 prevê redução quando preenchidos requisitos legais; não é automática para todo réu primário, pois exige também não dedicação a atividades criminosas nem integração em organização criminosa."], ["Art. 28 e art. 33 têm verbos e consequências distintos.", "Quantidade é um dos elementos, não critério único.", "Tráfico privilegiado do art. 33, § 4º, depende de todos os requisitos."], "Pessoa é encontrada com substância e o enunciado não informa circunstâncias de venda.", "A destinação deve ser determinada pelo conjunto do art. 28, § 2º; quantidade isolada ou ausência de venda observada não decide automaticamente."),
      section("penal-crimes-especie-topico-6", "6. Violência doméstica e legislação especial", ["A Lei Maria da Penha estabelece mecanismos de prevenção e proteção para violência doméstica e familiar contra a mulher. O art. 5º define contextos de violência doméstica/familiar; o art. 7º enumera formas, como violência física, psicológica, sexual, patrimonial e moral. São conceitos úteis para identificar incidência da lei, sem que cada forma corresponda automaticamente a um único tipo penal.", "Medidas protetivas de urgência têm finalidade preventiva e podem ser aplicadas conforme a lei, independentemente de tipificação penal final, observados seus requisitos. A Lei 14.994/2024 alterou o tratamento penal do feminicídio e de crimes relacionados; consulte as redações atuais.", "A legislação especial convive com o Código Penal. Para enquadrar fato, indique se a lei cria tipo próprio, modifica pena, prevê medida protetiva ou estabelece procedimento. Não trate a lei protetiva como se fosse um tipo penal genérico."], ["Lei 11.340: contexto doméstico/familiar e formas de violência.", "Medida protetiva não é sinônimo de condenação criminal.", "Lei 14.994/2024 alterou o CP em matéria de feminicídio; use redação vigente."], "Uma ameaça ocorre em contexto de violência doméstica e a vítima solicita proteção imediata.", "Examine a incidência da Lei 11.340 e os requisitos de medida protetiva; a existência da medida não substitui a análise de tipo, prova e devido processo penal."),
      section("penal-crimes-especie-topico-7", "7. Roteiro para classificar crime em espécie", ["Leia o verbo e o elemento subjetivo do tipo; identifique bem jurídico, sujeito e objeto; confira circunstâncias qualificadoras/majorantes; situe consumação ou tentativa; e aplique lei no tempo. Em crimes especiais, verifique se a lei especial altera tipo, pena, rito ou proteção.", "A questão pode combinar fatos patrimoniais, funcionais, familiares ou de drogas. Separe cada conduta e cada agente. Concurso de tipos não significa concurso de crimes: antes, avalie especialidade e consunção.", "Os exemplos e exercícios são autorais, não são itens oficiais ou reproduções de prova OAB. O módulo é uma seleção metodológica, não promete cobrir todo o catálogo penal nem substitui atualização legislativa."], ["Faça correspondência elemento por elemento.", "Não presuma pena, qualificadora ou causa de aumento.", "Consulte lei especial e alterações recentes."], "A questão utiliza a expressão cotidiana “roubo”, mas narra fraude sem violência e entrega voluntária do bem após erro.", "A classificação jurídica não segue o nome usado no enunciado: compare a fraude com o art. 171 e a violência/ameaça com o art. 157."),
    ],
    reviewQuestions: [
      review("1. Qual é a diferença básica entre furto e roubo?", "Roubo inclui violência ou grave ameaça (ou meio legalmente descrito); furto é subtração sem esses elementos no tipo básico.", "Compare o meio de execução e confira a redação atual dos arts. 155 e 157.", "CP, arts. 155 e 157."),
      review("2. O que caracteriza estelionato?", "Obtenção de vantagem ilícita em prejuízo alheio mediante fraude que induz ou mantém alguém em erro.", "O art. 171 tem elementos próprios; fraude sem vantagem/prejuízo pode exigir outro enquadramento.", "CP, art. 171."),
      review("3. O que distingue concussão de corrupção passiva?", "Concussão usa o verbo exigir; corrupção passiva envolve solicitar, receber ou aceitar promessa de vantagem.", "Verbos legais ajudam a identificar o tipo e consumação.", "CP, arts. 316 e 317."),
      review("4. Qual elemento especial o art. 319 exige?", "Finalidade de satisfazer interesse ou sentimento pessoal.", "A ilegalidade ou atraso isolado não basta.", "CP, art. 319."),
      review("5. Quantidade de droga é o único critério para distinguir art. 28 e art. 33?", "Não. A lei determina considerar conjunto de natureza/quantidade, local, condições, circunstâncias e conduta.", "A quantidade é elemento relevante, mas não decide sozinha.", "Lei nº 11.343/2006, art. 28, § 2º; art. 33."),
      review("6. O tráfico privilegiado do art. 33, § 4º, é automático para primário?", "Não. Além da primariedade e bons antecedentes, a lei exige não dedicação criminosa nem integração em organização criminosa.", "Todos os requisitos devem ser examinados.", "Lei nº 11.343/2006, art. 33, § 4º."),
      review("7. O que a Lei Maria da Penha define em seus arts. 5º e 7º?", "Contextos de violência doméstica/familiar e formas de violência contra a mulher.", "As formas não correspondem automaticamente a um tipo penal único.", "Lei nº 11.340/2006, arts. 5º e 7º."),
      review("8. Como a Lei 14.994/2024 alterou a análise do feminicídio?", "Criou tipo autônomo no art. 121-A do Código Penal, exigindo consulta à redação atual.", "Não se deve usar material antigo que o apresente apenas como qualificadora do homicídio.", "CP, art. 121-A; Lei nº 14.994/2024."),
    ],
    exercises: [
      exercise("penal-crimes-ex-1", "A subtração é realizada mediante grave ameaça contra a vítima. Qual tipo deve ser investigado?", "B", "CP, art. 157.", [
        { text: "Furto simples", why: "O tipo básico de furto não contém grave ameaça como meio de execução." }, { text: "Roubo", why: "O art. 157 prevê subtração mediante violência ou grave ameaça." }, { text: "Apropriação indébita", why: "Esse tipo parte de posse/detenção legítima anterior." }, { text: "Estelionato", why: "A situação descreve ameaça, não indução em erro por fraude." },
      ]),
      exercise("penal-crimes-ex-2", "Agente exige vantagem indevida em razão da função pública. Qual tipo penal corresponde ao verbo descrito?", "D", "CP, art. 316.", [
        { text: "Corrupção passiva", why: "O art. 317 usa solicitar, receber ou aceitar promessa; aqui o verbo é exigir." }, { text: "Prevaricação", why: "Não há ato de ofício praticado para interesse/sentimento pessoal." }, { text: "Peculato", why: "Não foi narrada apropriação/desvio de bem sob posse funcional." }, { text: "Concussão", why: "O art. 316 descreve exigir vantagem indevida em razão da função." },
      ]),
      exercise("penal-crimes-ex-3", "Para distinguir posse para consumo pessoal e tráfico, a Lei de Drogas manda considerar:", "A", "Lei nº 11.343/2006, arts. 28, § 2º, e 33.", [
        { text: "Conjunto de natureza/quantidade, local, condições, circunstâncias e conduta", why: "O art. 28, § 2º, estabelece avaliação conjunta." }, { text: "Somente a quantidade", why: "Quantidade não é critério exclusivo." }, { text: "Somente confissão", why: "A lei não institui confissão como critério único." }, { text: "A renda do acusado", why: "Renda não substitui os elementos legais do art. 28, § 2º." },
      ]),
      exercise("penal-crimes-ex-4", "Servidor retarda ato de ofício para satisfazer sentimento pessoal. Qual crime pode estar caracterizado, se comprovados os demais requisitos?", "C", "CP, art. 319.", [
        { text: "Concussão", why: "Não há exigência de vantagem indevida." }, { text: "Peculato", why: "Não há apropriação ou desvio de bem." }, { text: "Prevaricação", why: "O art. 319 prevê retardar/deixar de praticar ato para satisfazer interesse ou sentimento pessoal." }, { text: "Corrupção ativa", why: "O agente descrito é funcionário e não oferece vantagem a outro." },
      ]),
      exercise("penal-crimes-ex-5", "Uma vítima relata violência psicológica em relação doméstica. Qual legislação contém formas de violência e mecanismos protetivos específicos?", "B", "Lei nº 11.340/2006, arts. 5º e 7º.", [
        { text: "Somente CP, art. 121", why: "O art. 121 trata de homicídio, não define todo o sistema protetivo." }, { text: "Lei Maria da Penha", why: "A Lei 11.340 define contexto e formas de violência e prevê mecanismos protetivos." }, { text: "Lei de Drogas", why: "A lei trata de delitos e políticas sobre drogas." }, { text: "Código Civil apenas", why: "O enunciado envolve legislação protetiva penal e cível especial." },
      ]),
      exercise("penal-crimes-ex-6", "Segundo a redação atual introduzida pela Lei 14.994/2024, o feminicídio está tipificado:", "D", "CP, art. 121-A; Lei nº 14.994/2024.", [
        { text: "Somente como agravante genérica", why: "A lei criou tipo autônomo no CP." }, { text: "No art. 129", why: "O art. 129 disciplina lesão corporal." }, { text: "Na Lei de Drogas", why: "O diploma é estranho ao tema." }, { text: "Como tipo autônomo no art. 121-A do CP", why: "A Lei 14.994/2024 inseriu o art. 121-A." },
      ]),
    ], sources: [cp, cf, drogas, mariaPenha],
  },
};
